//! Poseidon2 over Goldilocks — **the in-circuit hash**, ported to Zig so the protocol's
//! note-commitment / nullifier / Merkle hashing equals `lattica-prover-p3`'s circuit byte-for-byte
//! (audit finding C-03). Width 8, S-box x⁷, 8 full + 22 partial rounds, vetted `p3-goldilocks`
//! constants. The constants + the known-answer vectors below are generated by
//! `lattica-prover-p3 … --bin dump_p2`; the KAT tests pin equality with the circuit.
//!
//! Domain separation (matches `joinsplit_air`): a distinct tag in lane 0 of each data hash
//! (`DOM_OWN/DOM_CM/DOM_NF`); the Merkle merge is untagged (2-to-1 over digests).

const std = @import("std");
const field = @import("field.zig");
const Felt = field.Felt;

const add = field.add;
const mul = field.mul;

pub const DIGEST_FELTS: usize = 4;
pub const Digest = [DIGEST_FELTS]Felt;

// domain-separation tags (must match joinsplit_air::DOM_*)
pub const DOM_OWN: u64 = 1;
pub const DOM_CM: u64 = 2;
pub const DOM_NF: u64 = 3;

// --- vetted constants (generated; do not edit by hand — regenerate via dump_p2) ---------------
