    .{ 14868588146468890290, 12825281145595371185, 13097885453579304196, 7905326782341128063, 14167525334039893569, 2082169701994688927, 12190787523818595537, 12602917751946636 },
    .{ 14890907856876319003, 16552240149997473409, 5634093690795187558, 4883714163685656967, 12440776365164557866, 3923800234666204307, 9858064884105950259, 16040043470428402038 },
};
const EXT_FINAL = [4][8]u64{
    .{ 94277733998400326, 10891359798487446420, 18280773820738154043, 13714589910668449566, 10639034072771185213, 14148790895768484219, 18341268649720100165, 3096672942770686236 },
    .{ 12277596046563557393, 400461754528604020, 12955488253560265444, 11773677676764285572, 4833837465239476573, 17645852643693996619, 6605134696140007471, 588040525114200273 },
    .{ 11001741536026769411, 17917086578469406776, 14893530806420712543, 727997185253761138, 3443873847340254325, 13095911531247069692, 8330737046680948619, 6014364575875986011 },
