// --- permutation -------------------------------------------------------------------------------

fn sbox(x: Felt) Felt {
    return field.pow(x, 7);
}

/// M4 applied to a 4-element chunk (matches p3 `apply_mat4`).
fn applyMat4(x: *[4]Felt) void {
    const t01 = add(x[0], x[1]);
    const t23 = add(x[2], x[3]);
    const t0123 = add(t01, t23);
    const t01123 = add(t0123, x[1]);
    const t01233 = add(t0123, x[3]);
    x[3] = add(t01233, add(x[0], x[0]));
    x[1] = add(t01123, add(x[2], x[2]));
    x[0] = add(t01123, t01);
    x[2] = add(t01233, t23);
}

/// External (light MDS) layer for width 8: M4 on each chunk, then the outer circulant sums.
fn mdsLight(s: *[8]Felt) void {
    applyMat4(s[0..4]);
    applyMat4(s[4..8]);
    var sums: [4]Felt = undefined;
    inline for (0..4) |k| sums[k] = add(s[k], s[k + 4]);
    inline for (0..8) |i| s[i] = add(s[i], sums[i % 4]);
}

/// Internal layer: `state[i] = state[i]·DIAG[i] + Σ state`.
fn internalLinear(s: *[8]Felt) void {
    var sum: Felt = 0;
    for (s) |x| sum = add(sum, x);
    inline for (0..8) |i| s[i] = add(mul(s[i], DIAG8[i]), sum);
}

fn fullRound(s: *[8]Felt, rc: [8]u64) void {
    inline for (0..8) |i| s[i] = sbox(add(s[i], rc[i]));
    mdsLight(s);
}

fn partialRound(s: *[8]Felt, rc: u64) void {
    s[0] = sbox(add(s[0], rc));
    internalLinear(s);
}

/// The Poseidon2-Goldilocks permutation (in place).
pub fn permute(state: *[8]Felt) void {
    mdsLight(state);
    for (EXT_INIT) |rc| fullRound(state, rc);
    for (INTERNAL) |rc| partialRound(state, rc);
    for (EXT_FINAL) |rc| fullRound(state, rc);
}

// --- domain-tagged hashes (match joinsplit_air) -----------------------------------------------

/// `H(domain ‖ elems)`, digest = first 4 lanes. `elems.len()` must be ≤ 7.
fn h(domain: u64, elems: []const Felt) Digest {
    var s = [_]Felt{0} ** 8;
    s[0] = domain;
    for (elems, 0..) |e, i| s[1 + i] = e;
    permute(&s);
    return s[0..4].*;
}

pub fn recipient(nk0: Felt, nk1: Felt, d: Felt) Digest {
    return h(DOM_OWN, &.{ nk0, nk1, d }); // 128-bit nullifier key + diversifier
}

/// Two-permutation commitment (128-bit note randomness; must match joinsplit_air::commit):
///   H1 = perm([DOM_CM, rcp(4), value, rho0, rho1]); cm = perm([H1(4), rcm0, rcm1, 0, 0]).
pub fn commitNote(rcp: Digest, value: Felt, rho: [2]Felt, rcm: [2]Felt, asset: Felt) Digest {
    var a = [_]Felt{ DOM_CM, rcp[0], rcp[1], rcp[2], rcp[3], value, rho[0], rho[1] };
    permute(&a);
    var b = [_]Felt{ a[0], a[1], a[2], a[3], rcm[0], rcm[1], asset, 0 }; // lane6 = hidden asset id
    permute(&b);
    return b[0..4].*;
}

pub fn nullifierHash(nk0: Felt, nk1: Felt, rho: [2]Felt, pos: Felt) Digest {
    return h(DOM_NF, &.{ nk0, nk1, rho[0], rho[1], pos });
}

/// 2-to-1 Merkle compression `H(l ‖ r)` (untagged, fills all 8 lanes).
pub fn merge(l: Digest, r: Digest) Digest {
    var s = [_]Felt{ l[0], l[1], l[2], l[3], r[0], r[1], r[2], r[3] };
    permute(&s);
    return s[0..4].*;
}

/// Reduce up to 8 little-endian bytes to a field element (mod p).
pub fn feltLE(b: []const u8) Felt {
    var x: u64 = 0;
    var i: usize = 0;
    while (i < b.len and i < 8) : (i += 1) x |= @as(u64, b[i]) << @intCast(i * 8);
    return x % field.P;
}

/// Interpret a 32-byte hash as a 4-element digest (4 little-endian limbs, each mod p).
pub fn digestFromBytes(bytes: [32]u8) Digest {
    var d: Digest = undefined;
    inline for (0..4) |i| d[i] = feltLE(bytes[i * 8 .. i * 8 + 8]);
    return d;
}

/// Canonical little-endian bytes of a 4-element digest (the on-chain 32-byte hash).
pub fn digestBytes(d: Digest) [32]u8 {
    var out: [32]u8 = undefined;
    inline for (0..4) |i| std.mem.writeInt(u64, out[i * 8 ..][0..8], d[i], .little);
    return out;
}

// --- known-answer tests vs the Rust circuit (generated by dump_p2) -----------------------------

const testing = std.testing;

test "poseidon2: permute matches the circuit (KAT)" {
    var s = [8]Felt{ 0, 1, 2, 3, 4, 5, 6, 7 };
    permute(&s);
    const want = [8]Felt{ 147757088869797140, 9575016380710448421, 1936818598401832023, 11876560440185116837, 933995228215617535, 8686652366030325867, 8297621998173199092, 17588152731440920923 };
    try testing.expectEqual(want, s);
}

test "poseidon2: domain-tagged hashes match the circuit (KAT)" {
    const rcp = recipient(7, 70, 5);
    try testing.expectEqual(Digest{ 12117778067832875188, 10864618677725252023, 10798466789515031362, 11357075400886075001 }, rcp);
    try testing.expectEqual(Digest{ 10467251944032595743, 15951568864992726969, 686076823887839950, 2164025591647199027 }, commitNote(rcp, 1000, .{ 11, 211 }, .{ 100, 300 }, 9));
    try testing.expectEqual(Digest{ 2354178473207051117, 1485123762175440172, 16578445368892662424, 12056995742034228502 }, nullifierHash(7, 70, .{ 11, 211 }, 9));
    try testing.expectEqual(Digest{ 15506260347376358782, 2994144798473533345, 1833939590059144543, 15204941819943812974 }, merge(.{ 1, 2, 3, 4 }, .{ 5, 6, 7, 8 }));
}
